export class MissingLocaleDataError extends Error {
  constructor(locale: string) {
    super(`No CLDR formatting data is loaded for locale '${locale}'.`);
  }
}

export function dataFor(locale: string): CldrLocaleData {
  const found = CLDR_DATA[locale];
  if (found === undefined) {
    throw new MissingLocaleDataError(locale);
  }
  return found;
}

// ---------------------------------------------------------------------------
// Plural selection.
// ---------------------------------------------------------------------------

function operandsOf(n: number): PluralOperands {
  const absN = Math.abs(n);
  if (Number.isInteger(absN)) {
    return { n: absN, i: absN, v: 0, f: 0 };
  }
  const [intText, fracText] = absN.toString().split('.');
  return { n: absN, i: Number(intText), v: fracText.length, f: Number(fracText) };
}

function operandValue(name: string, operands: PluralOperands): number {
  switch (name) {
    case 'n':
      return operands.n;
    case 'i':
      return operands.i;
    case 'v':
      return operands.v;
    case 'f':
      return operands.f;
    default:
      throw new Error(`Plural relation names operand '${name}', but only n/i/v/f are supported.`);
  }
}

function rangeMatches(value: number, rangeText: string): boolean {
  const trimmed = rangeText.trim();
  if (trimmed.includes('..')) {
    const [low, high] = trimmed.split('..');
    return value >= Number(low) && value <= Number(high);
  }
  return value === Number(trimmed);
}

function comparisonMatches(comparison: string, operands: PluralOperands): boolean {
  const negate = comparison.includes('!=');
  const [left, right] = comparison.split(negate ? '!=' : '=');
  if (right === undefined) {
    throw new Error(`Plural relation comparison '${comparison}' has neither '=' nor '!='.`);
  }
  const trimmedLeft = left.trim();
  let value: number;
  if (trimmedLeft.includes('%')) {
    const [operandName, modulusText] = trimmedLeft.split('%');
    value = operandValue(operandName.trim(), operands) % Number(modulusText.trim());
  } else {
    value = operandValue(trimmedLeft, operands);
  }
  const matched = right.split(',').some((part) => rangeMatches(value, part));
  return matched !== negate;
}

function evaluatePluralRelation(relation: string, operands: PluralOperands): boolean {
  return relation
    .split(/\s+or\s+/)
    .some((conjunction) =>
      conjunction.split(/\s+and\s+/).every((comparison) => comparisonMatches(comparison.trim(), operands)),
    );
}

const PLURAL_CATEGORY_ORDER: readonly PluralCategory[] = ['zero', 'one', 'two', 'few', 'many'];

export function pluralCategory(n: number, locale: string): PluralCategory {
  const rules = dataFor(locale).pluralRules;
  const operands = operandsOf(n);
  for (const category of PLURAL_CATEGORY_ORDER) {
    const relation = rules[category];
    if (relation !== undefined && evaluatePluralRelation(relation, operands)) {
      return category;
    }
  }
  return 'other';
}

// ---------------------------------------------------------------------------
// Number pattern parsing -- one closed CLDR pattern grammar
// (`#`/`0`/`,`/`.`/literal prefix-suffix text), applied to the decimal,
// currency and percent patterns alike.
// ---------------------------------------------------------------------------

interface ParsedNumberPattern {
  readonly prefix: string;
  readonly suffix: string;
  readonly groupSize: number;
  readonly grouped: boolean;
  readonly minFractionDigits: number;
  readonly maxFractionDigits: number;
}

function parseNumberPattern(pattern: string): ParsedNumberPattern {
  const digitIndexes: number[] = [];
  for (let index = 0; index < pattern.length; index += 1) {
    if (pattern[index] === '#' || pattern[index] === '0') {
      digitIndexes.push(index);
    }
  }
  const first = digitIndexes[0];
  const last = digitIndexes[digitIndexes.length - 1];
  const prefix = pattern.slice(0, first);
  const suffix = pattern.slice(last + 1);
  const numeric = pattern.slice(first, last + 1);
  const dotIndex = numeric.indexOf('.');
  const intPart = dotIndex === -1 ? numeric : numeric.slice(0, dotIndex);
  const fracPart = dotIndex === -1 ? '' : numeric.slice(dotIndex + 1);
  const commaIndex = intPart.lastIndexOf(',');
  const groupSize = commaIndex === -1 ? 0 : intPart.length - commaIndex - 1;
  return {
    prefix,
    suffix,
    groupSize,
    grouped: commaIndex !== -1,
    minFractionDigits: fracPart.split('').filter((ch) => ch === '0').length,
    maxFractionDigits: fracPart.length,
  };
}

function groupInteger(digits: string, groupSize: number): string {
  if (groupSize <= 0) {
    return digits;
  }
  const groups: string[] = [];
  let end = digits.length;
  while (end > 0) {
    const start = Math.max(0, end - groupSize);
    groups.unshift(digits.slice(start, end));
    end = start;
  }
  return groups.join(',');
}

function formatWithPattern(
  value: number,
  pattern: string,
  symbols: CldrNumberSymbols,
  fractionDigits?: number,
): string {
  const parsed = parseNumberPattern(pattern);
  const minFractionDigits = fractionDigits ?? parsed.minFractionDigits;
  const maxFractionDigits = fractionDigits ?? parsed.maxFractionDigits;
  return renderFixed(value < 0, Math.abs(value).toFixed(maxFractionDigits), parsed, symbols, minFractionDigits);
}

/**
 * The magnitude text *fixed* (`1234.50`) in *parsed*'s grouping and literal text, its trailing
 * fraction zeros dropped down to *minFractionDigits* digits, signed when *negative*.
 */
function renderFixed(
  negative: boolean,
  fixed: string,
  parsed: ParsedNumberPattern,
  symbols: CldrNumberSymbols,
  minFractionDigits: number,
): string {
  const [intText, fracTextRaw] = fixed.split('.');
  let fracText = fracTextRaw ?? '';
  while (fracText.length > minFractionDigits && fracText.endsWith('0')) {
    fracText = fracText.slice(0, -1);
  }
  const groupedInt = groupInteger(intText, parsed.grouped ? parsed.groupSize : 0)
    .split(',')
    .join(symbols.group);
  const body = fracText.length > 0 ? `${groupedInt}${symbols.decimal}${fracText}` : groupedInt;
  const sign = negative ? symbols.minusSign : '';
  return `${sign}${parsed.prefix}${body}${parsed.suffix}`;
}

// ---------------------------------------------------------------------------
// An amount of money with a chosen number of fraction digits -- computed on
// the digits of the exact decimal, never through binary floating point.
// ---------------------------------------------------------------------------

/** A decimal amount: its sign, all its digits, and how many of them follow the point. */
interface DecimalAmount {
  readonly negative: boolean;
  readonly digits: string;
  readonly scale: number;
}

const DECIMAL_AMOUNT = /^(-?)(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/;

/**
 * The exact decimal *value* spells: a number as its shortest decimal text (what the program
 * wrote), decimal text as written -- never the binary fraction a double holds. A value that is no
 * finite number or decimal text is refused.
 */
function decimalAmountOf(value: number | string): DecimalAmount {
  const match = DECIMAL_AMOUNT.exec(String(value));
  if (match === null) {
    throw new RangeError(`A money amount needs a finite number or decimal text; got ${String(value)}.`);
  }
  const [, sign, whole, fraction = '', exponent = '0'] = match;
  const scale = fraction.length - Number(exponent);
  const digits = `${whole}${fraction}`;
  return scale < 0
    ? { negative: sign === '-', digits: digits + '0'.repeat(-scale), scale: 0 }
    : { negative: sign === '-', digits, scale };
}

/** *digits* plus one, as digits. */
function incrementDigits(digits: string): string {
  const out = digits.split('');
  let index = out.length - 1;
  while (index >= 0 && out[index] === '9') {
    out[index] = '0';
    index -= 1;
  }
  if (index < 0) {
    return `1${out.join('')}`;
  }
  out[index] = String(Number(out[index]) + 1);
  return out.join('');
}

/** Whether the *dropped* digits after *kept* round it up: past the half, or on it with an odd last digit. */
function roundsUp(kept: string, dropped: string): boolean {
  if (dropped[0] !== '5') {
    return dropped[0] > '5';
  }
  return /[1-9]/.test(dropped.slice(1)) || Number(kept[kept.length - 1]) % 2 === 1;
}

/** *amount*'s magnitude with exactly *fractionDigits* fraction digits, rounded half to even on its exact digits. */
function roundedMagnitude(amount: DecimalAmount, fractionDigits: number): string {
  let digits: string;
  if (fractionDigits >= amount.scale) {
    digits = amount.digits + '0'.repeat(fractionDigits - amount.scale);
  } else {
    const dropped = amount.scale - fractionDigits;
    const padded = amount.digits.padStart(dropped + 1, '0');
    const kept = padded.slice(0, padded.length - dropped);
    digits = roundsUp(kept, padded.slice(padded.length - dropped)) ? incrementDigits(kept) : kept;
  }
  const padded = digits.padStart(fractionDigits + 1, '0');
  const whole = padded.slice(0, padded.length - fractionDigits).replace(/^0+(?=\d)/, '');
  return fractionDigits === 0 ? whole : `${whole}.${padded.slice(padded.length - fractionDigits)}`;
}

/** *amount* through *pattern* with exactly *fractionDigits* digits; a negative amount that rounds to zero has no sign. */
function formatAmountWithPattern(
  amount: DecimalAmount,
  pattern: string,
  symbols: CldrNumberSymbols,
  fractionDigits: number,
): string {
  const fixed = roundedMagnitude(amount, fractionDigits);
  const negative = amount.negative && /[1-9]/.test(fixed);
  return renderFixed(negative, fixed, parseNumberPattern(pattern), symbols, fractionDigits);
}

/** *fractionDigits* of the formatter *member*, refused unless it is a whole number, 0 or more. */
function requireFractionDigits(member: string, fractionDigits: number): number {
  if (!Number.isInteger(fractionDigits) || fractionDigits < 0) {
    throw new RangeError(`${member} needs a whole number of fraction digits, 0 or more; got ${fractionDigits}.`);
  }
  return fractionDigits;
}

// ---------------------------------------------------------------------------
// Date/time pattern token substitution.
// ---------------------------------------------------------------------------

const DATE_TIME_FIELD_LETTERS = new Set(['y', 'M', 'd', 'H', 'h', 'm', 's', 'a']);

function tokenizePattern(pattern: string): string[] {
  const tokens: string[] = [];
  let index = 0;
  while (index < pattern.length) {
    const char = pattern[index];
    if (DATE_TIME_FIELD_LETTERS.has(char)) {
      let end = index;
      while (end < pattern.length && pattern[end] === char) {
        end += 1;
      }
      tokens.push(pattern.slice(index, end));
      index = end;
    } else {
      tokens.push(char);
      index += 1;
    }
  }
  return tokens;
}

function pad2(value: number): string {
  return value < 10 ? `0${value}` : String(value);
}

function applyDateTimePattern(value: Date, pattern: string, data: CldrLocaleData): string {
  const hour24 = value.getHours();
  const hour12 = hour24 % 12 || 12;
  const dayPeriod: 'am' | 'pm' = hour24 < 12 ? 'am' : 'pm';
  return tokenizePattern(pattern)
    .map((token) => {
      const field = token[0];
      const width = token.length;
      switch (field) {
        case 'y':
          return width === 2 ? pad2(value.getFullYear() % 100) : String(value.getFullYear());
        case 'M':
          if (width >= 4) return data.monthNamesWide[value.getMonth()];
          if (width === 3) return data.monthNamesShort[value.getMonth()];
          return width === 2 ? pad2(value.getMonth() + 1) : String(value.getMonth() + 1);
        case 'd':
          return width === 2 ? pad2(value.getDate()) : String(value.getDate());
        case 'H':
          return width === 2 ? pad2(hour24) : String(hour24);
        case 'h':
          return width === 2 ? pad2(hour12) : String(hour12);
        case 'm':
          return width === 2 ? pad2(value.getMinutes()) : String(value.getMinutes());
        case 's':
          return width === 2 ? pad2(value.getSeconds()) : String(value.getSeconds());
        case 'a':
          return data.dayPeriods[dayPeriod];
        default:
          return token;
      }
    })
    .join('');
}

// ---------------------------------------------------------------------------
// Relative time -- plural-category-dispatched templates from the extract's
// own `relativeTime` unit tables, never a hardcoded singular/plural binary.
// ---------------------------------------------------------------------------

/** The units a relative time is shown in, each with the whole seconds one of it lasts, smallest
 * first: the shared date and time rule every client target renders. */
export const RELATIVE_UNITS: readonly (readonly [string, number])[] = [
  ['second', 1],
  ['minute', 60],
  ['hour', 3600],
  ['day', 86400],
];

/** From this many seconds ago on, a relative time is shown as the short date. */
export const RELATIVE_SPAN_SECONDS = 604800;

/** A pattern `Fmt.dateTime` shows a date and time in. */
export type DateTimePattern = 'date' | 'shortDate' | 'time' | 'dateTime' | 'relative';

// ---------------------------------------------------------------------------
// Public, locale-parameterized Fmt.* logic. `format.ts`'s `LocaleFormat`
// reads its current locale and delegates to these; the CLDR fixture test
// calls these directly, one locale at a time, with no session/DI object.
// ---------------------------------------------------------------------------

/**
 * `Fmt.number`: *value* in *locale*'s decimal pattern, or with *fractionDigits* exactly that
 * many digits after the locale's decimal separator. A negative or non-whole digit count is refused.
 */
export function formatNumber(value: number, locale: string, fractionDigits?: number): string {
  if (fractionDigits !== undefined) {
    requireFractionDigits('Fmt.number', fractionDigits);
  }
  const data = dataFor(locale);
  return formatWithPattern(value, data.numberPatterns.decimal, data.numberSymbols, fractionDigits);
}

/**
 * `Fmt.money`: *value* -- a number, or a decimal as its wire text -- in *locale*'s currency
 * pattern, or with *fractionDigits* exactly that many digits after the decimal separator, rounded
 * half to even on the exact decimal *value* spells (`2.5` is `$2` at zero digits). A negative or
 * non-whole digit count is refused.
 */
export function formatMoney(value: number | string, locale: string, fractionDigits?: number): string {
  const data = dataFor(locale);
  const pattern = data.numberPatterns.currency.split('¤').join(data.currency.symbol);
  if (fractionDigits === undefined) {
    return formatWithPattern(Number(value), pattern, data.numberSymbols);
  }
  const digits = requireFractionDigits('Fmt.money', fractionDigits);
  return formatAmountWithPattern(decimalAmountOf(value), pattern, data.numberSymbols, digits);
}

const SYMBOL_FIRST = /^\p{S}/u;
const SYMBOL_LAST = /\p{S}$/u;
const NO_BREAK_SPACE = String.fromCharCode(0xa0);

/**
 * *pattern* with its `¤` replaced by *symbol*. CLDR's currency spacing: a symbol that is not
 * itself a symbol character (`KWD`, `FCFA`, as opposed to `$` or `€`) directly beside the digits
 * is separated from them by a no-break space.
 */
function withCurrencySymbol(pattern: string, symbol: string): string {
  const beforeDigits = /¤[#0]/.test(pattern) && !SYMBOL_LAST.test(symbol) ? NO_BREAK_SPACE : '';
  const afterDigits = /[#0]¤/.test(pattern) && !SYMBOL_FIRST.test(symbol) ? NO_BREAK_SPACE : '';
  return pattern.split('¤').join(`${afterDigits}${symbol}${beforeDigits}`);
}

export class UnknownCurrencyError extends Error {
  constructor(currency: string) {
    super(`'${currency}' is not an ISO 4217 currency code the formatting data carries.`);
  }
}

/**
 * `Fmt.minorMoney`: a whole number of *currency*'s minor units in *locale*'s currency pattern,
 * with that currency's symbol and its own number of fraction digits (2500 EUR is `€25.00`, 2500
 * JPY is `¥2,500`). A code outside the ISO 4217 list, or an amount that is not whole, is refused.
 * With *fractionDigits* the amount shows exactly that many digits instead (1100000 USD at zero is
 * `$11,000`): fewer than the currency's own round half to even on the exact amount (2550 USD at
 * zero is `$26`, 2450 is `$24`), more pad with zeros. A negative or non-whole digit count is refused.
 */
export function formatMinorMoney(minorUnits: number, currency: string, locale: string, fractionDigits?: number): string {
  const data = dataFor(locale);
  if (!Object.prototype.hasOwnProperty.call(data.currencies, currency)) {
    throw new UnknownCurrencyError(currency);
  }
  if (!Number.isInteger(minorUnits)) {
    throw new RangeError(`Fmt.minorMoney needs a whole number of minor units; got ${minorUnits}.`);
  }
  const named = data.currencies[currency];
  const pattern = withCurrencySymbol(data.numberPatterns.currency, named.symbol);
  if (fractionDigits === undefined) {
    return formatWithPattern(minorUnits / 10 ** named.digits, pattern, data.numberSymbols, named.digits);
  }
  const digits = requireFractionDigits('Fmt.minorMoney', fractionDigits);
  const whole = decimalAmountOf(minorUnits);
  return formatAmountWithPattern(
    { negative: whole.negative, digits: whole.digits, scale: named.digits },
    pattern,
    data.numberSymbols,
    digits,
  );
}

function namedCurrency(currency: string, locale: string): CldrNamedCurrency {
  const data = dataFor(locale);
  if (!Object.prototype.hasOwnProperty.call(data.currencies, currency)) {
    throw new UnknownCurrencyError(currency);
  }
  return data.currencies[currency];
}

/** Whether *currency* is an ISO 4217 code the formatting data carries. */
export function isCurrencyCode(currency: string, locale: string): boolean {
  return Object.prototype.hasOwnProperty.call(dataFor(locale).currencies, currency);
}

/**
 * What a money input shows for a whole number of *currency*'s minor units: the major-unit amount
 * as a person writes it -- the locale's decimal separator, the currency's own number of fraction
 * digits, no grouping and no symbol (2500 EUR is `25.00`, 2500 JPY is `2500`). Computed on the
 * digits of the integer, never through a floating-point division.
 */
export function minorUnitsInputText(minorUnits: number, currency: string, locale: string): string {
  const named = namedCurrency(currency, locale);
  if (!Number.isSafeInteger(minorUnits)) {
    throw new RangeError(`A money input needs a whole number of minor units; got ${minorUnits}.`);
  }
  const symbols = dataFor(locale).numberSymbols;
  const digits = String(Math.abs(minorUnits)).padStart(named.digits + 1, '0');
  const whole = digits.slice(0, digits.length - named.digits);
  const fraction = digits.slice(digits.length - named.digits);
  const sign = minorUnits < 0 ? symbols.minusSign : '';
  return `${sign}${whole}${fraction === '' ? '' : symbols.decimal}${fraction}`;
}

/** What a money input's text holds: nothing, a whole number of minor units, or text that is no amount. */
export type MinorUnitsInput = { readonly kind: 'empty' } | { readonly kind: 'invalid' } | { readonly kind: 'amount'; readonly minorUnits: number };

const MINOR_UNITS_EMPTY: MinorUnitsInput = { kind: 'empty' };
const MINOR_UNITS_INVALID: MinorUnitsInput = { kind: 'invalid' };
const ASCII_DIGITS = /^[0-9]*$/;

/**
 * The whole number of *currency*'s minor units a money input's *text* writes, read in *locale*: digits,
 * the locale's decimal separator, a leading minus sign. A grouping separator or an inner space is
 * invalid, not skipped: where one locale groups with the character another uses as its decimal point
 * (`1.5`), skipping it would read a different amount than the person wrote. An amount with more
 * fraction digits than the currency has -- a cent and a half -- is invalid, never rounded.
 */
export function parseMinorUnitsInput(text: string, currency: string, locale: string): MinorUnitsInput {
  const named = namedCurrency(currency, locale);
  const symbols = dataFor(locale).numberSymbols;
  let rest = text.trim();
  if (rest === '') {
    return MINOR_UNITS_EMPTY;
  }
  let negative = false;
  for (const minus of [symbols.minusSign, '-']) {
    if (rest.startsWith(minus)) {
      negative = true;
      rest = rest.slice(minus.length);
      break;
    }
  }
  const parts = rest.split(symbols.decimal);
  const whole = parts[0];
  const fraction = parts.length === 2 ? parts[1] : '';
  const wellFormed =
    parts.length <= 2 &&
    ASCII_DIGITS.test(whole) &&
    ASCII_DIGITS.test(fraction) &&
    whole.length + fraction.length > 0 &&
    fraction.length <= named.digits;
  if (!wellFormed) {
    return MINOR_UNITS_INVALID;
  }
  const magnitude = Number(`${whole}${fraction.padEnd(named.digits, '0')}`);
  if (!Number.isSafeInteger(magnitude)) {
    return MINOR_UNITS_INVALID;
  }
  return { kind: 'amount', minorUnits: negative ? -magnitude : magnitude };
}

export function formatPercent(value: number, locale: string): string {
  const data = dataFor(locale);
  return formatWithPattern(value * 100, data.numberPatterns.percent, data.numberSymbols);
}

export function formatDate(value: Date, locale: string): string {
  const data = dataFor(locale);
  return applyDateTimePattern(value, data.datePatterns.short, data);
}

export function formatMediumDate(value: Date, locale: string): string {
  const data = dataFor(locale);
  return applyDateTimePattern(value, data.datePatterns.medium, data);
}

export function formatTime(value: Date, locale: string): string {
  const data = dataFor(locale);
  return applyDateTimePattern(value, data.timePatterns.short, data);
}

export function formatDateTime(value: Date, locale: string): string {
  return `${formatDate(value, locale)} ${formatTime(value, locale)}`;
}

/** Pure, wall-clock-free relative-time rendering: the unit/amount are
 * already computed (by `FormatService.relative` from an elapsed `Date`
 * delta, or directly by a test) -- this function only picks the
 * plural-dispatched template and substitutes `{0}`. */
export function formatRelativeAmount(unit: string, amount: number, locale: string): string {
  const data = dataFor(locale);
  const forms = data.relativeTime[unit];
  if (forms === undefined) {
    throw new Error(`No relative-time forms for unit '${unit}' in locale '${locale}'.`);
  }
  const category = pluralCategory(amount, locale);
  const template = forms[category] ?? forms['other'];
  return template.replace('{0}', String(amount));
}

const WHITESPACE_RUN = /\s+/u;
const GRAPHEME_SEGMENTER = new Intl.Segmenter('und', { granularity: 'grapheme' });

/** The first user-perceived character (grapheme cluster) of *word*, uppercased. */
function firstGraphemeUpper(word: string): string {
  for (const part of GRAPHEME_SEGMENTER.segment(word)) {
    return part.segment.toUpperCase();
  }
  return '';
}

/** Up to two uppercase initials: the first grapheme of the first and of the
 * last whitespace-separated word. One word yields one initial; no words yield
 * `''`. Deliberately locale-free (`toUpperCase()` takes no locale and grapheme
 * segmentation carries no locale data), so it is not part of the CLDR fixture
 * and the shared fixture has no case for it. */
export function formatInitials(text: string): string {
  const words = text.split(WHITESPACE_RUN).filter((word) => word.length > 0);
  if (words.length === 0) {
    return '';
  }
  const first = firstGraphemeUpper(words[0]);
  if (words.length === 1) {
    return first;
  }
  return first + firstGraphemeUpper(words[words.length - 1]);
}

/** The unit and whole amount *elapsedSeconds* is shown in as a relative time: the largest unit of
 * `RELATIVE_UNITS` it has reached and the whole number of it passed (never rounded up, at least
 * one); `null` when it is shown as the short date instead -- from `RELATIVE_SPAN_SECONDS` on, or
 * below zero (a moment after now). */
export function relativeUnitAndAmount(elapsedSeconds: number): readonly [string, number] | null {
  if (elapsedSeconds < 0 || elapsedSeconds >= RELATIVE_SPAN_SECONDS) {
    return null;
  }
  let [unit, unitSeconds] = RELATIVE_UNITS[0];
  for (const [candidate, seconds] of RELATIVE_UNITS) {
    if (elapsedSeconds >= seconds) {
      [unit, unitSeconds] = [candidate, seconds];
    }
  }
  return [unit, Math.max(1, Math.floor(elapsedSeconds / unitSeconds))];
}

/** *value* as text in *locale*, in *pattern*: `date` (medium date), `shortDate`, `time`,
 * `dateTime` (short date and time) or `relative`, counted to *now*. Analysis refuses any other
 * word, so one here is an error, never a default. */
export function formatDateTimeAt(value: Date, pattern: DateTimePattern, locale: string, now: Date): string {
  switch (pattern) {
    case 'date':
      return formatMediumDate(value, locale);
    case 'shortDate':
      return formatDate(value, locale);
    case 'time':
      return formatTime(value, locale);
    case 'dateTime':
      return formatDateTime(value, locale);
    case 'relative': {
      const relative = relativeUnitAndAmount(Math.floor((now.getTime() - value.getTime()) / 1000));
      return relative === null ? formatDate(value, locale) : formatRelativeAmount(relative[0], relative[1], locale);
    }
    default:
      throw new Error(`'${String(pattern)}' is no date and time pattern.`);
  }
}
